function stableRead(filename,cap,{gid=20,executable=false}={}){
  const named=fs.lstatSync(filename);assert.ok(named.isFile()&&!named.isSymbolicLink());
  assert.equal(named.uid,501);assert.equal(named.gid,gid);assert.equal(named.nlink,1);assert.equal(named.mode&0o022,0);
  if(executable)assert.ok(named.mode&0o100);
  const fd=fs.openSync(filename,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);
  const tuple=s=>[s.dev,s.ino,s.mode,s.nlink,s.uid,s.gid,s.size,s.mtimeMs,s.ctimeMs];
  try{assert.deepEqual(tuple(fs.fstatSync(fd)),tuple(named));assert.ok(named.size<=cap);
    const bytes=Buffer.alloc(cap+1);let at=0,reads=0;
    for(;;){assert.ok(++reads<=16384);const n=fs.readSync(fd,bytes,at,bytes.length-at,null);if(!n)break;at+=n;assert.ok(at<=cap);}
    assert.deepEqual(tuple(fs.fstatSync(fd)),tuple(named));assert.deepEqual(tuple(fs.lstatSync(filename)),tuple(named));return bytes.subarray(0,at);
  }finally{fs.closeSync(fd);}
}
