  const terminal=await capturePerl(home,programBytes);
  const after={node:hash(stableRead(NODE,1048576,{gid:80,executable:true})),entry:fileHash(material.entryPath),source:fileHash(material.sourcePath),program:hash(initialPreflight(caseKind).programBytes),observer:fileHash(material.observer),manifest:fileHash(material.manifestPath)};
  writeJSON(path.join(home,'pins-after.original.json'),after);
