    assert.equal(ns.sequence,proof.sequence);assert.equal(ns.frameCount,proof.sequence-1);assert.equal(ns.inflight,proof.phase);assert.equal(ns.expected,proof.phase+1);assert.equal(ns.inputBytes,48*(proof.phase+1));
