    assert.ok(orders.length>0);assert.deepEqual(copy.launcherEvents.filter(e=>e.kind!=='physical-observation'),result.launcherEvents.filter(e=>e.kind!=='physical-observation'));
    assert.deepEqual(copy.physicalObservation.events,copy.launcherEvents.filter(e=>e.kind==='physical-observation'));
    assert.throws(()=>assertPhysicalObservationTrace(copy),{code:'ERR_ASSERTION'},name+' must refuse dropped observation DATA before physical4-vs0');
