  const launchers=result.forks.filter(f=>f.role==='source-launcher');assert.equal(launchers.length,2);for(const f of launchers){assert.equal(f.reaped,1);assert.equal(f.uncertain,0);assert.ok(Number.isSafeInteger(f.rawStatus)&&f.rawStatus>=0);assert.ok(f.stack.some(s=>s[2]==='main::task6a_origin_consume_entry_protocol'));}
