  const accumulated=ev.filter(e=>e.order<read.order&&e.kind==='read'&&e.role==='observer-stdout-r'&&e.bytes>0).reduce((n,e)=>n+e.bytes,0);assert.equal(accumulated,proof.captureOffset);
  const chunk=original.subarray(proof.captureOffset,proof.captureOffset+proof.chunkBytes);assert.equal(chunk.length,proof.chunkBytes);assert.equal(hash(chunk),proof.originalChunkSHA256);assert.ok(chunk.subarray(proof.frameOffset,proof.frameOffset+184).equals(frame));const modeled=Buffer.from(chunk);modeled.writeUInt32LE(1,proof.frameOffset+12);assert.ok(modeled.equals(delivered));assert.equal(hash(delivered),proof.modeledChunkSHA256);assert.notEqual(hash(chunk),hash(delivered));
