  const observerReap=ev.find(e=>e.kind==='wait'&&e.pid===result.nativeOriginalPID&&e.returned===e.pid);assert.ok(observerReap&&observerReap.order>arm.order);assert.ok(ev.filter(e=>e.order>arm.order&&e.kind==='wait'&&e.pid===result.parentOriginalPID).every(e=>e.order>observerReap.order));const nodeReap=ev.find(e=>e.kind==='wait'&&e.pid===result.parentOriginalPID&&e.returned===e.pid);assert.ok(nodeReap&&nodeReap.order>observerReap.order);
  assert.equal(p.acquisitions.length,4);assert.equal(p.after.state,'burned');assert.equal(p.after.cleanupAttempted,1);assert.equal(p.after.cleanupOK,1);assert.equal(p.after.private.acquisitionUnknown,0);assert.equal(p.after.private.keeper.length,4);assert.ok(p.after.private.keeper.every(k=>k.attempted===1&&k.closed===1&&k.live===null));
  for(const a of p.acquisitions){assert.equal(a.returned,1);assert.equal(a.errorHex,'');assert.equal(a.closeAttempts,1);assert.equal(a.closeReturned,1);assert.equal(a.live,null);}
  const active=p.events.filter(e=>e.event==='launcher-enrolled'||e.event==='before-source-write');assert.equal(active.length,early?3:8);assert.equal(active.filter(e=>e.event==='launcher-enrolled').length,2);for(const e of active){assert.equal(e.snapshot.state,'active');assert.equal(e.snapshot.ownedCount,4);assert.deepEqual(e.snapshot.owned.map(o=>o.shape),p.acquisitions.map(a=>a.shape));assert.deepEqual(e.snapshot.owned.map(o=>o.live),p.acquisitions.map(a=>a.fd));}
  const marks=active.filter(e=>e.event==='launcher-enrolled');assert.deepEqual(marks.map(e=>e.pid),launchers.map(f=>f.pid));for(const marker of active.filter(e=>e.event==='before-source-write')){const actual=ev.find(e=>e.order===marker.order+1);assert.ok(actual&&actual.kind==='write'&&actual.role===marker.role&&actual.origin==='actual-source-write');}
  const enters=p.events.filter(e=>e.event==='physical-epoch-enter'),ends=p.events.filter(e=>e.event==='physical-epoch-complete');assert.equal(enters.length,early?2:3);assert.equal(ends.length,enters.length);const paths=['/','/usr','/usr/bin','/usr/bin/perl','/','/usr','/usr/bin'];for(let i=0;i<enters.length;i++){assert.equal(ends[i].captureCount-enters[i].captureCount,7);const group=result.captures.slice(enters[i].captureCount,ends[i].captureCount);assert.equal(group.length,7);for(let n=0;n<7;n++){const c=group[n];assert.equal(c.requestedTool,'/bin/ls');assert.deepEqual(c.requestedArgs,['-lde',paths[n]]);assert.ok(c.launcherOrderAtDispatch>=enters[i].order&&c.launcherOrderAtDispatch<ends[i].order);}}
  const ready=ev.find(e=>e.kind==='read'&&e.role==='node-stdout-r'&&e.offset+e.bytes>=6),setup=ev.find(e=>e.kind==='close'&&e.role==='node-setup-r');assert.ok(ready&&setup&&ready.order<enters[1].order&&setup.order<enters[1].order&&ends[1].order<arm.order);if(!early){const third=ev.find(e=>e.kind==='read'&&e.role==='node-stdout-r'&&e.offset+e.bytes>=216);assert.ok(third&&third.order<enters[2].order&&ends[2].order<arm.order);}
  assert.equal(proof.physicalSnapshot.state,'active');assert.equal(proof.physicalSnapshot.ownedCount,4);assert.deepEqual(proof.physicalSnapshot.owned.map(o=>o.live),p.acquisitions.map(a=>a.fd));
  const closes=p.events.filter(e=>e.event==='actual-fixed-close');assert.equal(closes.length,4);assert.ok(closes.every(e=>e.order>nodeReap.order&&e.order>observerReap.order));assert.equal(p.events.filter(e=>e.event==='physical-epoch-complete').length,early?2:3);const last=Math.max(...closes.map(e=>e.order));assert.ok(result.handles.filter(h=>h.realm==='staged').every(h=>h.launcherOrderBeforeClose>=last));
