const SOURCE_MAIN_PROJECTIONS=[["sub task6a_origin_main {\n    task6a_origin_refuse() unless $<==0&&$>==0&&@ARGV==0;","sub task6a_origin_main {\n    task6a_origin_refuse() unless $<==501&&$>==501&&POSIX::getgid()==20&&POSIX::getegid()==20&&@ARGV==0;\n    g1_observe_entry('main-admitted');"],["sub task6a_origin_produce_source_vendor_staged_custody {","sub task6a_origin_produce_source_vendor_staged_custody {\n    g1_observe_entry('producer-entry');"],["sub task6a_origin_consume_entry_protocol {","sub task6a_origin_consume_entry_protocol {\n    g1_observe_entry('consumer-entry');"],["sub task6a_origin_release_staged_custody {","sub task6a_origin_release_staged_custody {\n    g1_observe_entry('staged-release-entry');"]];

// G1 TEST-only route. Production main/cold guards remain byteexact on disk.
// Main alone owns the chain; observations and capture supply no Source unwind.
const SOURCE_MAIN_TITLE='Perl Source main owns one publisher consumer release occurrence';
function sourceMainOccurrenceProgram(original,base,routes,username){
  const emitted=physicalLifetimeProgram(original,base,routes,username,'outer-main');
  let program=replaceOne(emitted.program,PHYSICAL_LIFETIME_SUFFIX,SOURCE_MAIN_SUFFIX);
  program=replaceOne(program,'\n#line 1 "Source.constructor.declarations.pl"\n','\n'+SOURCE_MAIN_OBSERVER+'\n#line 1 "Source.constructor.declarations.pl"\n');
  const projections=[...emitted.projections];
  for(const [from,to]of SOURCE_MAIN_PROJECTIONS){program=replaceOne(program,from,to);projections.push([from,to]);}
  return {program,projections};
}
