    assert.deepEqual(consumer.creatorCloseCounts,Array(13).fill(1));assert.deepEqual(consumer.creatorLive,Array(13).fill(null));assert.deepEqual(consumer.stagedCloseCounts,Array(12).fill(0));assert.ok(consumer.stagedLive.every(fd=>Number.isInteger(fd)&&fd>=3));
