    assert.deepEqual(release.physical.private.keeper.map(k=>[k.attempted,k.closed,k.live]),Array.from({length:4},()=>[1,1,null]));
    assert.deepEqual([release.constructor.node.reaped,release.constructor.node.uncertain,release.constructor.observer.reaped,release.constructor.observer.uncertain],[1,0,1,0]);
    assert.deepEqual(release.stagedCloseCounts,Array(12).fill(0));assert.ok(release.stagedLive.every(fd=>Number.isInteger(fd)&&fd>=3));
    assert.equal(result.after.stagedPhase,'released');assert.deepEqual(result.after.stagedCloseCounts,Array(12).fill(1));assert.deepEqual(result.after.stagedLive,Array(12).fill(null));
    assert.equal(result.after.helperCount,127);assert.equal(result.after.helpersSettled,1);
