    for(const [filename,sha]of [[m.observerPath,OBSERVER_SHA],[m.cSourcePath,C2_SHA],[m.abiPath,ABI_SHA]]){const p=constructorPin(filename,1048576);assert.equal(p.sha256,sha);before.push(p);}
