      helperOriginalCount:proof.helpers.length,sourceMaterialOriginalCount:result.handles.length,sourceEpochCount:2,witnessEpochCount:0,capsuleSHA256:OBSERVER_SHA,
      outer:result.outer,sourceEntries:result.sourceEntries,physicalObservation:result.physicalObservation,traceDeletionControls:proof.traceDeletionControls,
