  try{check();fd=fs.openSync(filename,'wx',0o600);let at=0;while(at<bytes.length){const request=Math.min(65536,bytes.length-at);fullCharge(ledger,request);check();const n=fs.writeSync(fd,bytes,at,request);assert.ok(n>0&&n<=request);record.written+=n;at+=n;fullPositive(ledger,n);check();}const st=fs.fstatSync(fd);identity=constructorIdentity(st);assert.deepEqual(constructorIdentity(fs.lstatSync(filename)),identity);assert.equal(st.size,bytes.length);record.identity=identity;}
