    assert.equal(snap.state,state,why);assert.equal(snap.ownsLedgers,1,why);assert.equal(snap.internal,internal,why);assert.equal(snap.cleanupAttempted,0,why);assert.equal(snap.cleanupOK,0,why);assert.equal(snap.fileBurned,state==='burned'?1:0,why);assert.equal(snap.fileReleased,0,why);assert.equal(snap.ownedCount,count,why);assert.equal(snap.owned.length,count,why);
