    for(const [k,v]of [['outer.claimed',1],['outer.complete',0],['outer.unwindStarted',1],['outer.releaseAttempted',0],['outer.primaryPlain',observer?0:1],['staged.originalCount',12],['staged.closeAttemptCount',0],['staged.liveCount',12],['physical.originalCount',4],['physical.closeAttemptCount',0],['physical.liveCount',4],['startup.epochs',3],['startup.finishStarted',1],['startup.finishOutcome',0],['startup.primarySet',1],['startup.releaseCount',0],['startup.secondaryCount',1],['helpers.originalCount',observer?104:78],['helpers.notDefinitelySettledCount',observer?0:1],['helpers.logicalBurn',observer?0:1]])assert.equal(jointNumber(rows,label+'.'+k),v);
    assert.equal(jointText(rows,label+'.startup.rawPrimary'),refusal);assert.equal(jointText(rows,label+'.startup.secondary.0.stage'),'outer-quiescence');assert.equal(jointText(rows,label+'.startup.secondary.0.error'),'TASK6A_JOINT_STARTUP_REFUSED\n');for(let i=1;i<8;i++)for(const f of ['stage','error'])assert.equal(jointText(rows,label+'.startup.secondary.'+i+'.'+f),null);for(let i=0;i<2;i++)for(const f of ['attempted','completed','returned','error','success'])assert.equal(jointText(rows,label+'.startup.release.'+i+'.'+f),null);
